  'memory_boost.simon.heading': {'en': "Watch the growing light pattern and repeat it. Pick a difficulty.", 'hi': "बढ़ता रोशनी पैटर्न देखें और दोहराएं। कठिनाई चुनें।", 'hinglish': "Badhta light pattern dekho aur repeat karo. Difficulty chuno.", 'te': "పెరుగుతున్న లైట్ నమూనా చూసి మళ్లీ చేయి. కష్టస్థాయి ఎంచుకో.", 'ta': "வளரும் ஒளி வரிசையைப் பார்த்துத் திரும்பச் செய். கடினநிலையைத் தேர்வு செய்.", 'pa': "ਵਧਦਾ ਰੌਸ਼ਨੀ ਪੈਟਰਨ ਦੇਖੋ ਅਤੇ ਦੁਹਰਾਓ। ਮੁਸ਼ਕਲ ਚੁਣੋ।", 'bho': "बढ़त रोसनी के पैटर्न देखीं आ दोहराईं। कठिनाई चुनीं।", 'mr': "वाढत जाणारा प्रकाश क्रम पाहा आणि पुन्हा करा. काठिण्य निवडा.", 'sa': "वर्धमानं प्रकाशक्रमं पश्यत, पुनः कुरुत च। काठिन्यं चिनुत।"},
  'memory_boost.simon.desc.easy': {'en': "Slow lights, 4 pads, one forgiven mistake.", 'hi': "धीमी रोशनी, 4 पैड, एक गलती माफ़।", 'hinglish': "Slow lights, 4 pads, ek galti maaf.", 'te': "నెమ్మదిగా లైట్లు, 4 ప్యాడ్లు, ఒక తప్పు క్షమించబడుతుంది.", 'ta': "மெதுவான ஒளி, 4 பட்டைகள், ஒரு தவறு மன்னிக்கப்படும்.", 'pa': "ਹੌਲੀ ਰੌਸ਼ਨੀ, 4 ਪੈਡ, ਇੱਕ ਗਲਤੀ ਮਾਫ਼।", 'bho': "धीमा रोसनी, 4 पैड, एगो गलती माफ।", 'mr': "मंद दिवे, 4 पॅड, एक चूक माफ.", 'sa': "मन्दप्रकाशः, 4 फलकानि, एकः दोषः क्षम्यः।"},
  'memory_boost.simon.desc.medium': {'en': "Classic speed, 4 pads.", 'hi': "सामान्य रफ़्तार, 4 पैड।", 'hinglish': "Classic speed, 4 pads.", 'te': "సాధారణ వేగం, 4 ప్యాడ్లు.", 'ta': "வழக்கமான வேகம், 4 பட்டைகள்.", 'pa': "ਆਮ ਰਫ਼ਤਾਰ, 4 ਪੈਡ।", 'bho': "सामान्य रफ्तार, 4 पैड।", 'mr': "सामान्य वेग, 4 पॅड.", 'sa': "सामान्यवेगः, 4 फलकानि।"},
  'memory_boost.simon.desc.hard': {'en': "Fast lights, 4 pads.", 'hi': "तेज़ रोशनी, 4 पैड।", 'hinglish': "Fast lights, 4 pads.", 'te': "వేగమైన లైట్లు, 4 ప్యాడ్లు.", 'ta': "வேகமான ஒளி, 4 பட்டைகள்.", 'pa': "ਤੇਜ਼ ਰੌਸ਼ਨੀ, 4 ਪੈਡ।", 'bho': "तेज रोसनी, 4 पैड।", 'mr': "जलद दिवे, 4 पॅड.", 'sa': "शीघ्रप्रकाशः, 4 फलकानि।"},
  'memory_boost.simon.desc.extreme': {'en': "Blazing speed with 6 pads.", 'hi': "6 पैड के साथ बिजली जैसी रफ़्तार।", 'hinglish': "6 pads ke saath super fast speed.", 'te': "6 ప్యాడ్లతో మెరుపు వేగం.", 'ta': "6 பட்டைகளுடன் மின்னல் வேகம்.", 'pa': "6 ਪੈਡਾਂ ਨਾਲ ਬਿਜਲੀ ਵਰਗੀ ਰਫ਼ਤਾਰ।", 'bho': "6 पैड के साथे बिजली नियर रफ्तार।", 'mr': "6 पॅडसह विजेसारखा वेग.", 'sa': "6 फलकैः सह विद्युद्वेगः।"},
